interface.definition:
  a!localVariables(
    {
      /* ── PAGE HEADER ── */
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_sideBySideLayout"(
            alignVertical: "MIDDLE",
            items: {
              /* Icon chip */
              #"SYSTEM_SYSRULES_sideBySideItem"(
                width: "MINIMIZE",
                item: #"SYSTEM_SYSRULES_stampField"(
                  labelPosition: "COLLAPSED",
                  icon: "building-o",
                  backgroundColor: "ACCENT",
                  contentColor: "STANDARD",
                  size: "MEDIUM",
                  marginBelow: "NONE"
                )
              ),
              /* Title + subtitle */
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: {
                  #"SYSTEM_SYSRULES_headingField"(
                    marginBelow: "NONE",
                    text: "Organization Management",
                    fontWeight: "SEMI_BOLD",
                    size: "MEDIUM",
                    headingTag: "H1"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    marginAbove: "EVEN_LESS",
                    marginBelow: "NONE",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "View and manage organizations you have access to",
                      color: "SECONDARY"
                    )
                  )
                }
              ),
              /* Primary action — UUID-qualified */
              #"SYSTEM_SYSRULES_sideBySideItem"(
                width: "MINIMIZE",
                item: #"SYSTEM_SYSRULES_recordActionField_v1"(
                  actions: #"SYSTEM_SYSRULES_recordActionItem"(
                    action: #"urn:appian:record-action:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/a7039225-8a7e-4bc5-87b6-69b91f8b8e03"
),
style: "SIDEBAR_PRIMARY",
align: "END"
)
)
}
)
},
